def build_context(
    rendered_template: str,
    variables: dict[str, Any],
    template_str: str = "",
    max_context_tokens: int = _DEFAULT_MAX_TOKENS,
) -> str:
    total_tokens = _estimate_tokens(rendered_template)
    if total_tokens <= max_context_tokens:
        return rendered_template

    truncation_candidates = [
        "test_results", "iteration_history", "current_code",
        "code", "learning_log", "prior_lessons",
    ]

    trimmed_vars = dict(variables)
    for field in truncation_candidates:
        if field not in trimmed_vars:
            continue
        original = str(trimmed_vars[field])
        field_budget = max_context_tokens // 2
        trimmed_vars[field] = _truncate_to_tokens(original, field_budget)

    # ACTUALLY RE-RENDER with truncated variables
    if template_str:
        re_rendered = template_str.format(**trimmed_vars)
    else:
        re_rendered = rendered_template
        for field, value in trimmed_vars.items():
            original = str(variables.get(field, ""))
            if original != str(value):
                re_rendered = re_rendered.replace(original, str(value))

    return re_rendered

@pytest.mark.asyncio async def test_memory_bomb_handled(): result = await execute("x = 'a' * (10**9)", "assert True", timeout=5.0) assert not result.passed
@pytest.mark.asyncio async def test_import_error_captured(): result = await execute("import nonexistent_module_xyz", "assert True") assert not result.passed assert "ModuleNotFoundError" in result.exception_type or "ModuleNotFoundError" in result.stderr
@pytest.mark.asyncio async def test_solution_and_test_code_both_empty(): result = await execute("", "pass") assert result.passed

"""Tests for LLM Router retry and fallback behavior."""
import pytest
from llm.router import LLMRouter
from llm.base import BaseLLMProvider, InferenceRequest, InferenceResponse
from llm.schema_validator import StructuredOutputError

class BadThenGoodProvider(BaseLLMProvider):
    def __init__(self):
        self.call_count = 0

    @property
    def provider_name(self) -> str:
        return "test"

    @property
    def model_name(self) -> str:
        return "test"

    async def infer(self, request: InferenceRequest) -> InferenceResponse:
        self.call_count += 1
        if self.call_count < 3:
            return InferenceResponse(text="not json", provider="test", model="test")
        return InferenceResponse(
            text='{"code":"def f(): pass","explanation":"ok"}',
            provider="test", model="test"
        )

class AlwaysBadProvider(BaseLLMProvider):
    @property
    def provider_name(self) -> str:
        return "test"

    @property
    def model_name(self) -> str:
        return "test"

    async def infer(self, request: InferenceRequest) -> InferenceResponse:
        return InferenceResponse(text="garbage", provider="test", model="test")

@pytest.mark.asyncio
async def test_router_retries_on_schema_failure():
    provider = BadThenGoodProvider()
    router = LLMRouter(provider=provider)
    result = await router.call(
        role="generator", template_key="initial",
        variables={"task_description": "test", "learning_log": ""}
    )
    assert provider.call_count == 3
    assert "def f" in result["code"]

@pytest.mark.asyncio
async def test_router_raises_after_max_retries():
    router = LLMRouter(provider=AlwaysBadProvider())
    with pytest.raises(StructuredOutputError):
        await router.call(
            role="generator", template_key="initial",
            variables={"task_description": "test", "learning_log": ""}
        )

