from langgraph.types import Send

def fan_out_repairs(state):
    strategies = [
        {"name": "minimal_fix", "instruction": "Change ONLY the failing line(s). Do not restructure."},
        {"name": "restructure", "instruction": "Rewrite the core algorithm keeping the same interface."},
        {"name": "add_guards", "instruction": "Add input validation and edge-case guards without changing core logic."},
    ]
    return [
        Send("parallel_generate", {
            **state,
            "repair_strategy": f"{state.get('repair_strategy', '')}\n\nApproach: {s['instruction']}",
            "strategy_name": s["name"],
        })
        for s in strategies
    ]

def select_best_repair(state):
    candidates = state.get("parallel_repairs", [])
    def score(c):
        both = c["spec_passed"] and c["adv_passed"]
        return (both, c["spec_passed"], -(c["spec_failures"] + c["adv_failures"]))
    candidates.sort(key=score, reverse=True)
    best = candidates[0] if candidates else None
    if best:
        return {
            "current_code": best["code"],
            "last_execution_passed": best["spec_passed"] and best["adv_passed"],
            "parallel_repairs": [],
        }
    return {"parallel_repairs": []}
